import createClient from 'openapi-fetch';
import { getClientVersionHeaders } from '../db-content-api/utilities/clientVersionHeaders.js';
import { applyContentApiAuth, getDevJwt, invalidateDevJwt } from './auth.js';
import { withRateLimitRetries } from './withRateLimitRetries.js';
/** The sole request entry point for Content API endpoints in the Payload plugin. */ export function createContentApiClient(options) {
    const baseUrl = new URL(options.baseUrl);
    if (options.requestTimeoutMs !== undefined && (!Number.isFinite(options.requestTimeoutMs) || options.requestTimeoutMs <= 0 || options.requestTimeoutMs > 2_147_483_647)) {
        throw new RangeError('requestTimeoutMs must be between 0 (exclusive) and 2147483647 milliseconds');
    }
    const versionHeaders = getClientVersionHeaders();
    const fetchWithRetries = withRateLimitRetries({
        fetchImplementation: fetch,
        warn: (message)=>options.logger.warn(message)
    });
    async function send(input, init, rawOptions) {
        const original = new Request(input, init);
        if (new URL(original.url).origin !== baseUrl.origin) {
            throw new Error('Content API client cannot request a different origin');
        }
        if (rawOptions?.unauthenticatedDevEndpoint && !new URL(original.url).pathname.startsWith('/dev/')) {
            throw new Error('Unauthenticated Content API requests are only allowed for dev endpoints');
        }
        original.signal.throwIfAborted();
        const deadlineController = new AbortController();
        const signal = AbortSignal.any([
            original.signal,
            deadlineController.signal
        ]);
        const timeout = options.requestTimeoutMs === undefined ? undefined : globalThis.setTimeout(()=>deadlineController.abort(new DOMException('Content API request timed out', 'TimeoutError')), options.requestTimeoutMs);
        try {
            const request = new Request(original.clone(), {
                signal
            });
            for (const [name, value] of Object.entries(versionHeaders)){
                request.headers.set(name, value);
            }
            if (!rawOptions?.unauthenticatedDevEndpoint) {
                await applyContentApiAuth(request, options);
            }
            signal.throwIfAborted();
            let response = await fetchWithRetries(request);
            signal.throwIfAborted();
            if (response.status === 401 && options.auth.mode === 'devJwt' && !rawOptions?.unauthenticatedDevEndpoint) {
                options.logger.info?.('Dev JWT expired, refreshing...');
                invalidateDevJwt(options.baseUrl, options.contentSystemId);
                const refreshedToken = await getDevJwt({
                    baseUrl: options.baseUrl,
                    contentSystemId: options.contentSystemId,
                    logger: options.logger,
                    signal
                });
                signal.throwIfAborted();
                const retryRequest = new Request(original.clone(), {
                    signal
                });
                for (const [name, value] of Object.entries(versionHeaders)){
                    retryRequest.headers.set(name, value);
                }
                retryRequest.headers.set('Authorization', `Bearer ${refreshedToken}`);
                response = await fetchWithRetries(retryRequest);
            }
            signal.throwIfAborted();
            if (!response.ok && response.status !== 429) {
                options.logger.error?.({
                    msg: `HTTP ${response.status} from ${request.url}`,
                    status: response.status,
                    statusText: response.statusText
                });
            }
            return response;
        } catch (error) {
            // Node's abortable waits may wrap the original timeout/cancellation reason in AbortError.
            signal.throwIfAborted();
            throw error;
        } finally{
            globalThis.clearTimeout(timeout);
        }
    }
    const api = createClient({
        baseUrl: options.baseUrl,
        fetch: send
    });
    return {
        api,
        request (path, init, rawOptions) {
            const url = new URL(path, baseUrl);
            return send(url, init, rawOptions);
        }
    };
}
